SELECT COUNT(*)
FROM ccds_profile_tombstone
WHERE station_id = #{stationId}

SELECT COUNT(*)
FROM ccds_profile_tombstone
WHERE station_id = #{stationId}
  AND name_norm = #{nameNorm}
  AND name_released_at IS NULL

SELECT COUNT(*)
FROM ccds_profile_tombstone
WHERE station_id = #{stationId}
  AND nfc_norm = #{nfcNorm}
  AND nfc_released_at IS NULL

SELECT COUNT(*)
FROM ccds_profile_tombstone
WHERE station_id = #{stationId}
  AND archive_no = #{archiveNo}
  AND archive_released_at IS NULL
